 "content": "from collections import Counter


def transform(grid):
    """Extract the right-hand panel and mark its non-background cells."""
    if not grid or not grid[0]:
        return []
    height, width = len(grid), len(grid[0])
    divider = next(
        (c for c in range(width)
         if all(grid[r][c] == grid[0][c] for r in range(height))
         and grid[0][c] != 0),
        None,
    )
    if divider is None:
        raise ValueError("missing solid vertical divider")
    panel = [row[divider + 1:] for row in grid]
    counts = Counter(value for row in panel for value in row)
    background = counts.most_common(1)[0][0]
    return [[2 if value != background else 0 for value in row] for row in panel]
